import fs from "node:fs";
import path from "node:path";
import { spawnSync } from "node:child_process";
import { pathToFileURL } from "node:url";

export async function gate({ referenceDir, submissionDir }) {
  const submissionPath = path.join(submissionDir, "answer.mjs");
  const pinnedPath = path.join(referenceDir, "pinned-test-cases.txt");
  const runnerPath = path.join(referenceDir, "_run_pinned.mjs");
  if (!fs.existsSync(submissionPath)) {
    return { accept: false, reason: "submission missing answer.mjs" };
  }
  if (!fs.existsSync(pinnedPath)) {
    return { accept: false, reason: "pinned-test-cases.txt missing" };
  }
  const pinnedTests = fs.readFileSync(pinnedPath, "utf8");
  const subUrl = pathToFileURL(path.resolve(submissionPath)).href;
  const runnerSrc = [
    "import assert from 'node:assert/strict';",
    "const failures = [];",
    "function test(name, fn) {",
    "  try { fn(); } catch (e) { failures.push(name + ': ' + (e && e.message ? e.message : String(e))); }",
    "}",
    "let dedupeSorted;",
    "try {",
    "  const mod = await import(" + JSON.stringify(subUrl) + ");",
    "  dedupeSorted = mod.dedupeSorted;",
    "} catch (e) {",
    "  console.log('GATE_RESULT:' + JSON.stringify({ accept: false, reason: 'import failed: ' + e.message }));",
    "  process.exit(0);",
    "}",
    "if (typeof dedupeSorted !== 'function') {",
    "  console.log('GATE_RESULT:' + JSON.stringify({ accept: false, reason: 'dedupeSorted not a function' }));",
    "  process.exit(0);",
    "}",
    pinnedTests,
    "if (failures.length) {",
    "  console.log('GATE_RESULT:' + JSON.stringify({ accept: false, reason: failures.join('; ') }));",
    "} else {",
    "  console.log('GATE_RESULT:' + JSON.stringify({ accept: true, reason: 'all pinned tests passed' }));",
    "}",
  ].join("\n");
  fs.writeFileSync(runnerPath, runnerSrc, "utf8");
  const result = spawnSync(process.execPath, [runnerPath], {
    encoding: "utf8",
    timeout: 15000,
    maxBuffer: 4 * 1024 * 1024,
    cwd: referenceDir,
  });
  const out = String(result.stdout || "") + String(result.stderr || "");
  const marker = "GATE_RESULT:";
  const idx = out.lastIndexOf(marker);
  if (idx !== -1) {
    const jsonLine = out.slice(idx + marker.length).split("\n")[0].trim();
    try {
      const parsed = JSON.parse(jsonLine);
      if (typeof parsed.accept === "boolean") {
        return { accept: parsed.accept, reason: String(parsed.reason || "") };
      }
    } catch (_) {}
  }
  if (result.error && result.error.code === "ETIMEDOUT") {
    return { accept: false, reason: "submission timed out" };
  }
  if (result.status !== 0) {
    return { accept: false, reason: "runner crashed: " + out.slice(0, 400) };
  }
  return { accept: false, reason: "no gate result from runner" };
}

